\begin{abstract}
The no-repeat symbolic coding of three-disk scattering has an exact finite-dimensional determinant, whereas the physical billiard flow is timed by nonconstant Euclidean flight lengths. We identify the precise obstruction to transferring the former to the latter through a single scalar clock substitution. For three equal disks of radius \(a\) with equilateral center spacing \(d>4a/\sqrt3\), the symmetric period-two and period-three owners have exact mean flight lengths \(d-2a\) and \(d-\sqrt3a\), respectively. Their positive gap \((2-\sqrt3)a\) proves that the physical roof is not cohomologous to a constant. It also rules out every owner- and repetition-preserving substitution \(z=e^{-cs}\) from the unit-roof Euler product to the physical flow and gives the minimax lower bound \((2-\sqrt3)a/2\) on any constant mean-roof approximation to these witnesses. Across the three geometries, a locked replay contains 2,241 primitive physical-orbit rows, 747 per geometry; three period-two owners match and 744 owners disagree at each geometry. Separately, we prove the exact determinant formula for the \(q\)-symbol no-repeat unit-roof family and the universal two-dimensional hyperbolic half-density factorization. These positive results belong to typed symbolic and stability-control objects; they do not transfer determinant credit to the physical flow. The paper supplies a rigorous clock-ownership negative control, a reproducible finite certificate, and a clear boundary between symbolic dynamics, semiclassical approximations, and exact scattering theory.
\end{abstract}

This paper asks:
\begin{quote}
\emph{Can the exact determinant of the unit-roof no-repeat shift be transferred to the physical three-disk flow by a scalar substitution \(z=e^{-cs}\) that preserves primitive owners and repetitions?}
\end{quote}

\begin{theorem}[unit-roof determinant family]\label{thm:qfamily}
For every integer \(q\ge2\), let \(A_q=J_q-I_q\). Then
\begin{equation}\label{eq:traceq}
 \tr(A_q^n)=(q-1)^n+(q-1)(-1)^n.
\end{equation}
The number of oriented primitive cyclic owners of length \(n\) is
\begin{equation}\label{eq:primitiveq}
 P_q(n)=\frac1n\sum_{r\mid n}\mu(r)\tr(A_q^{n/r}).
\end{equation}
For \(u\in\{+1,-1\}\),
\begin{equation}\label{eq:zetaq}
 \Zeta_{q,u}(z)
 :=\prod_{p\ \mathrm{primitive}}\left(1-u^{n_p}z^{n_p}\right)^{-1}
 =\det(I-uzA_q)^{-1}
 =\frac{1}{(1-(q-1)uz)(1+uz)^{q-1}}.
\end{equation}
In particular, \(\Zeta_{q,-1}(z)=\Zeta_{q,+1}(-z)\).
\end{theorem}

\begin{proof}
The all-ones vector is an eigenvector of \(A_q\) with eigenvalue \(q-1\). Its orthogonal complement has dimension \(q-1\), and \(J_q\) vanishes there, so \(A_q\) has eigenvalue \(-1\). Taking powers proves \cref{eq:traceq}. Every closed word is a traversal of a unique primitive cyclic word, and a primitive owner of length \(k\) has \(k\) starting points. Hence
\(\tr(A_q^n)=\sum_{k\mid n}kP_q(k)\); Möbius inversion gives \cref{eq:primitiveq}.

\begin{theorem}[hyperbolic half-density factorization]\label{thm:half}
Let \(M\in\operatorname{Sp}(2,\mathbb R)=\SL_2(\mathbb R)\) be hyperbolic with eigenvalues \(\sigma\Lambda\) and \(\sigma\Lambda^{-1}\), where \(\Lambda>1\) and \(\sigma\in\{+1,-1\}\). For \(r\ge1\),
\begin{equation}\label{eq:half}
 \frac{1}{\sqrt{|\det(I-M^r)|}}
 =\frac{\Lambda^{-r/2}}{|1-\sigma^r\Lambda^{-r}|}.
\end{equation}
\end{theorem}

\begin{proposition}[period-two mean]\label{prop:t2}
For any pair of disks, the symmetric orbit bouncing along their center line has
\[
 T_2=2(d-2a),\qquad \overline{\tau}_2=T_2/2=d-2a.
\]
\end{proposition}
\begin{proof}
The facing boundary points lie on the center line, each at distance \(a\) inward from its center. Their separation is \(d-2a\). Normal incidence reverses velocity and closes the orbit after the return flight.
\end{proof}

\begin{proposition}[period-three mean]\label{prop:t3}
The symmetric triangular orbit visiting all disks has
\[
 T_3=3(d-\sqrt3a),\qquad \overline{\tau}_3=T_3/3=d-\sqrt3a.
\]
\end{proposition}
\begin{proof}
Set \(C_0=(0,0)\), \(C_1=(d,0)\), and let \(G\) be the centroid. Unit vectors from \(C_0,C_1\) toward \(G\) are
\((\sqrt3/2,1/2)\) and \((-\sqrt3/2,1/2)\). Adding \(a\) times these vectors gives two collision points separated by \(d-\sqrt3a\). Rotational symmetry gives the same length on all sides. At each collision, symmetry around the center--centroid line gives equal incoming and outgoing angles.
\end{proof}

\begin{corollary}[positive clock gap]\label{cor:gap}
\[
 \overline{\tau}_3-\overline{\tau}_2=(2-\sqrt3)a>0.
\]
The gap is independent of \(d\).
\end{corollary}

\begin{theorem}[physical roof is not constant-cohomologous]\label{thm:noncohom}
For \(d>4a/\sqrt3\), the Euclidean flight roof of the equilateral three-disk
billiard is not cohomologous to a constant on the full no-repeat shift.
\end{theorem}
\begin{proof}
If \(\tau=c+h-h\circ\sigma\), every periodic owner has mean roof \(c\). The two witnesses would give simultaneously \(c=d-2a\) and \(c=d-\sqrt3a\), contradicting \cref{cor:gap}.
\end{proof}

\begin{theorem}[no owner-preserving scalar transfer]\label{thm:nontransfer}
For \(d>4a/\sqrt3\), there is no constant \(c>0\) for which \(z=e^{-cs}\)
converts the unit-roof primitive product into the physical-flight product
while preserving every primitive owner and repetition.
\end{theorem}
\begin{proof}
For a unit-roof owner \(p\) of symbolic length \(n_p\), substitution assigns weight \(e^{-scn_p}\); its \(r\)-fold repetition receives \(e^{-scrn_p}\). Equality with the physical factor for all \(s\) requires \(T_p=cn_p\) for every \(p\). The two symmetric owners force \(c=T_2/2=d-2a\) and \(c=T_3/3=d-\sqrt3a\), impossible by \cref{cor:gap}.
\end{proof}

\begin{corollary}[minimax lower bound]\label{cor:minimax}
For every constant \(c\in\mathbb R\),
\[
 \max\{|c-(d-2a)|,\ |c-(d-\sqrt3a)|\}
 \ge \frac{(2-\sqrt3)a}{2}.
\]
Equality holds at \(c=d-(2+\sqrt3)a/2\).
\end{corollary}
\begin{proof}
For \(x<y\), the triangle inequality gives
\(y-x\le|c-x|+|c-y|\le2\max(|c-x|,|c-y|)\). Substitute the exact means. Their midpoint equalizes errors.
\end{proof}

\begin{proposition}[dimensionless gap at the frozen geometry]
At \(d=6a\), the exact mean roofs are \(4a\) and \((6-\sqrt3)a\). Relative to the period-two calibration, the period-three mean mismatch is
\[
 \frac{(2-\sqrt3)a}{4a}=\frac{2-\sqrt3}{4}.
\]
\end{proposition}
\begin{proof}
Substitute \(d=6a\) in \cref{prop:t2,prop:t3} and divide the gap by \(4a\).
\end{proof}

